  renderHeroSlideshow(images,fallback){const valid=(Array.isArray(images)?images:[]).filter(src=>typeof src==='string'&&(src.startsWith('data:image/webp;base64,')||src.startsWith('data:image/jpeg;base64,')||src.startsWith('data:image/png;base64,')||/^https?:\/\//.test(src)||src.startsWith('assets/')));this.state.heroSlides=valid.length?valid:[this.safeExternalUrl(fallback||'assets/images/nw-03.svg','assets/images/nw-03.svg')];clearInterval(this.state.heroSlideTimer);const first=document.getElementById('hero-image'),second=document.getElementById('hero-image-next');if(!first||!second)return;this.state.heroSlideIndex=0;this.state.heroSlideActive=0;first.src=this.state.heroSlides[0];second.src=this.state.heroSlides[1%this.state.heroSlides.length];first.classList.add('opacity-100');first.classList.remove('opacity-0');second.classList.add('opacity-0');second.classList.remove('opacity-100');if(this.state.heroSlides.length<2)return;this.state.heroSlideTimer=setInterval(()=>{const incoming=this.state.heroSlideActive===0?1:0,next=(this.state.heroSlideIndex+1)%this.state.heroSlides.length,target=incoming===0?first:second,current=incoming===0?second:first;target.src=this.state.heroSlides[next];target.classList.add('opacity-100');target.classList.remove('opacity-0');current.classList.add('opacity-0');current.classList.remove('opacity-100');this.state.heroSlideIndex=next;this.state.heroSlideActive=incoming},5000)},
