  renderAdminUsers(){const box=document.getElementById('admin-user-list');box.innerHTML=this.state.users.length?this.state.users.map(u=>{const self=u.email===this.state.user.email;return '<article class="glass-panel flex flex-wrap items-center gap-3 rounded-2xl border border-white/10 p-4"><div class="min-w-0 flex-1"><strong class="block">'+this.safe(u.name||'Pengguna')+'</strong><span class="text-xs text-zinc-400">'+this.safe(u.email)+'</span></div><span class="rounded-full px-3 py-1 text-xs '+(u.role==='admin'?'bg-accent/10 text-accent':'bg-white/5 text-zinc-300')+'">'+(u.role==='admin'?'Admin':'Pembeli')+'</span>'+(self?'<span class="text-xs text-zinc-500">Akun aktif</span>':'<button data-user-email="'+this.safe(u.email)+'" data-user-role="'+(u.role==='admin'?'customer':'admin')+'" class="rounded-xl border border-white/10 px-3 py-2 text-xs hover:border-accent">'+(u.role==='admin'?'Jadikan pembeli':'Jadikan admin')+'</button>')+'</article>'}).join(''):'<p class="rounded-xl border border-dashed border-white/10 p-5 text-sm text-zinc-500">Belum ada pengguna.</p>';box.querySelectorAll('[data-user-email]').forEach(b=>b.onclick=()=>this.setUserRole(b.dataset.userEmail,b.dataset.userRole))},
