  newAddress(id=''){const form=document.getElementById('address-form');form.classList.remove('hidden');form.reset();document.getElementById('address-id').value=id;const a=this.state.addresses.find(x=>x.id===id);if(a){document.getElementById('address-label').value=a.label;document.getElementById('address-name').value=a.name;document.getElementById('address-phone').value=a.phone;document.getElementById('address-city').value=a.city;document.getElementById('address-line').value=a.address}},cancelAddress(){document.getElementById('address-form').classList.add('hidden')},
